/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.7 Multimodal dangerous goods
/// </summary>
[ExtensionOf(formStr(HMIMMultimodalDG))]
final class METHMIMMultimodalDGFrm_Extension
{
}

Method.Source:
    /// <summary>
    /// If the form was called from the custom Sales order shipments list page and the hazardous additions feature enabled
    /// hide the standard shipment ID field and display the custom shipment ID field.
    /// </summary>
    public void init()
    {
        const str shipmentIdControlName = 'HMIMMultimodalDG_METShipmentId';
        
        next init();

        if (this.args().caller()
           // cannot call this from extension, assuming it is enabled for Metcash
           //&& HMIMHazmatAdditionsFeature::isEnabled()
           && this.args().caller().name() == formStr(METSalesOrderShipmentListPage))
        {
            // get formRun
            FormRun formRun  = this as  FormRun;

            //get any datasource from the base form
            FormDataSource HMIMMultimodalDG_ds = formRun.datasource(FormDatasourceStr(HMIMMultimodalDG,HMIMMultimodalDG));

            // hide the standard shipment ID field and display the custom shipment ID field
            HMIMMultimodalDG_ds.object(fieldNum(HMIMMultimodalDG, ShipmentId)).visible(false);
     
            // at control level (does not work with datasource field) make custom shipment ID field visible
            formRun.design().controlName(shipmentIdControlName).visible(true);
        }
    }
